3	  TaskflowEventMap,
4	  TaskflowEventPayload,
5	  TaskflowEventType,
6	  Unsubscribe,
7	} from "@/types/event";
8	
9	/**
10	 * In-process, typed publish/subscribe bus.
11	 *
12	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
13	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
14	 * every reactive concern `subscribe()`s at module init (see
15	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
16	 * throwing handler never fails the emit or the sibling handlers.
17	 */
18	
19	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
20	
21	const handlers = new Map<TaskflowEventType, HandlerSet>();
22	
23	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
24	
25	/** Registers a handler for one event type. Call the return value to detach. */
26	export function subscribe<K extends TaskflowEventType>(
